INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c5fa7301-e669-5dec-8cc7-a0244e391048','TEXT','The Creek Sound Map','Luca liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Wednesday, Luca noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
