INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3dc67102-4221-5153-a48d-babbd94dd9e6','TEXT','The Windy Sculpture','Eli liked helping at the community hall, especially when there was a small job that nobody had planned. One Friday, Eli noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('05828d1a-f651-5f28-b530-9aa5e3ea74cc','TEXT','A Lantern for the Jetty — A Different Day','Amara liked helping at the sea fog, especially when there was a small job that nobody had planned. One Saturday, Amara noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
