INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('05a094fc-15fc-5742-8495-a57743f5daca','TEXT','A Lantern for the Jetty','Amara liked helping at the sea fog, especially when there was a small job that nobody had planned. One Thursday, Amara noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('34d8b0d3-b50f-52d0-acc6-9ce441583082','TEXT','The Seed Library — A Different Day','Kai liked helping at the community garden, especially when there was a small job that nobody had planned. One Wednesday, Kai noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
