INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('967b5b65-6603-5002-a004-f4a34750cccc','TEXT','The Seed Library','Kai liked helping at the community garden, especially when there was a small job that nobody had planned. One Wednesday, Kai noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
