INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('d93863b2-36d3-567a-81af-a51762dee349','TEXT','The Rainwater Notebook','Mia liked helping at the school courtyard, especially when there was a small job that nobody had planned. One Saturday, Mia noticed the rain gauge was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
