INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c66d97a1-a71a-535b-9dd1-c860032d96f1','TEXT','The Night Garden List','Sienna liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Tuesday, Sienna noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c4e5d221-da0b-5f6d-9070-717e4c53f7bb','TEXT','The Museum Window — A Different Day','Noah liked helping at the local museum, especially when there was a small job that nobody had planned. One Saturday, Noah noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
